import { isRecord, parseJsonBlock, readList, readOptionalString, readString, readStringList, unparsedIssue, type FieldContext } from "../shared/index.ts";
import { MAX_ANSWER_EXCERPT_CHARS, MAX_GOAL_CHARS, MAX_NOTES, MAX_NOTE_CHARS, MAX_PLAN_TASKS, MAX_REASON_CHARS } from "./constants.ts";
import { validateGraph } from "./graph.ts";
import { parseClassification } from "./parse-classification.ts";
import { parseTask } from "./parse-task.ts";
import type { ParsePlanResult, PlanIntent } from "./types.ts";

function fail(...issues: string[]): ParsePlanResult {
  return { ok: false, issues };
}

export function parsePlan(text: string, cwd: string): ParsePlanResult {
  const parsed = parseJsonBlock(text);
  if (!parsed.ok) return fail(unparsedIssue(parsed.issue, text, MAX_ANSWER_EXCERPT_CHARS));
  if (!isRecord(parsed.value)) return fail("Plan must be a JSON object");

  const issues: string[] = [];
  const ctx: FieldContext = { record: parsed.value, where: "Plan", issues };

  if (typeof parsed.value.noChangeNeeded === "string") {
    const reason = readString(ctx, "noChangeNeeded", MAX_REASON_CHARS);
    if (parsed.value.tasks !== undefined) issues.push('Plan must not combine "noChangeNeeded" with "tasks"');
    return reason !== null && issues.length === 0
      ? { ok: true, plan: { status: "no-change-needed", reason } }
      : fail(...issues);
  }

  const tasks = readList(ctx, "tasks", MAX_PLAN_TASKS, (raw, where, taskIssues) =>
    parseTask(raw, where, taskIssues, cwd),
  );
  const intent: PlanIntent = {
    goal: readOptionalString(ctx, "goal", MAX_GOAL_CHARS),
    assumptions: readStringList(ctx, "assumptions", { maxItems: MAX_NOTES, maxChars: MAX_NOTE_CHARS }),
    risks: readStringList(ctx, "risks", { maxItems: MAX_NOTES, maxChars: MAX_NOTE_CHARS }),
  };
  const classification = parseClassification(parsed.value.classification, issues);
  if (tasks.length === 0 && issues.length === 0) issues.push('Plan must contain at least one task or "noChangeNeeded"');
  if (issues.length === 0) issues.push(...validateGraph(tasks));
  return issues.length > 0 ? fail(...issues) : { ok: true, plan: { status: "ready", tasks, classification, intent } };
}
